INSERT INTO `perfis_tip` VALUES (852,112,'Igor Machado de Castro','Jogos divertidos na Cartoon Network','2018-09-11 20:10:55',136,'0','<pre>python manage.py rebuid_index</pre>','https://www.python.org/','','','None','2019-08-11 05:40:26','uploads/2019/08/11/download.png',NULL,NULL,NULL,'0','0','0','0','0','0','0','0','jogos-divertidos-na-cartoon-network','None','None','0'),(858,116,'Fernanda Brito','Just one suggestion: this could be the next kids outing','2019-06-19 01:47:31',140,'0','','','','','Estrada da Pena, 2710-609 Sintra, Portugal','2019-10-17 11:34:20','uploads/2019/10/17/pena.jpg','','','','0','0','0','0','0','0','0','0','just-one-suggestion-this-could-be-the-next-kids-outing','-22.841039423311717','-43.31232190132142','0'),(859,116,'Fernanda Brito','','2019-06-19 01:47:52',140,'0','','','','','','2019-08-01 02:24:27','uploads/2019/06/18/castelo2.jpg',NULL,NULL,NULL,'0','0','0','0','0','0','0','0','outdoor','-22.84126683649827','-43.31086277961732','0'),(882,116,'Fernanda Brito','The trip with the kids was amazing. The hotel had many outdoor activities.','2019-08-02 05:03:45',140,'0','<p><img src=\"data:image/jpeg;base64,\" style=\"width: 248px;\" class=\"fr-fic fr-dib\"></p><p style=\"text-align: center;\">Very comfortable and spacious room. It has 3 room mode.</p><p style=\"text-align: right;\"><br></p><p style=\"text-align: left;\"><img src=\"data:image/jpeg;base64,\" style=\"width: 241px;\" class=\"fr-fic fr-dib\"></p><p style=\"text-align: center;\">Spectacular and home cooked food. Typical farm restaurant.</p><p style=\"text-align: left;\"><br></p><p style=\"text-align: right;\"><img src=\"data:image/jpeg;base64,\" style=\"width: 235px;\" class=\"fr-fic fr-dib\"></p><p style=\"text-align: center;\">Colonial coffee farm. A historic and beautiful area that still has a small farm for children.</p>','','','','Rodovia Rio-Caxambu, Km 23, Engenheiro Passos - RJ','2019-10-17 11:45:27','uploads/2019/08/02/20170708_101000.jpg','','','','0','0','0','0','0','0','0','0','the-trip-with-the-kids-was-amazing-the-hotel-had-many-outdoor-activities','','','0'),(883,119,'Farfetch','Sapatos masculinos de alto padrão e conceito de moda mundial. ','2019-08-11 17:29:27',143,'0','<p><strong>HOGAN</strong></p><p><em>Olympia sneakers</em></p><p><br></p><p>Navy blue and grey leather Olympia sneakers from Hogan featuring a round toe, a lace-up front fastening, a brand embossed tongue, a branded insole, a logo to the outside and a flat rubber sole.</p><p><br></p><p>Feito em It&aacute;lia</p>','https://www.farfetch.com/br/shopping/men/hogan-olympia-sneakers-item-13522119.aspx?storeid=11719','','1.707,00','','2019-08-11 17:36:57','uploads/2019/08/11/derby.png',NULL,NULL,NULL,'0','0','0','0','0','0','0','0','sapatos-masculinos-de-alto-padrao-e-conceito-de-moda-mundial','','','0'),(892,107,'Igor M. Castro','The ride was amazing and the kids loved it.','2019-10-02 04:06:50',131,'0','','','','','Estrada Rio Caxambu, Km 23 s/n Distrito - Eng. Passos, Resende - RJ, 27555-000','2019-10-17 10:10:55','uploads/2019/10/02/05Penedo.jpg','uploads/2019/10/03/03penedo_1.jpg','uploads/2019/10/03/02penedo.jpg','uploads/2019/10/03/03penedo.jpg','1','0','0','0','0','0','0','1','the-ride-was-amazing-and-the-kids-loved-it','','','0'),(893,107,'Igor M. Castro','','2019-10-02 04:07:48',131,'0','','','1','','','2019-10-02 04:07:48','uploads/2019/10/02/22trespinheiros.jpg','uploads/2019/10/02/30trespinheiros.jpg','','','0','1','1','0','0','0','0','0','outdoor','','','0'),(900,114,'Pedro Brito','Olá. Sou o Pedro Brito','2019-10-17 10:50:14',138,'0','','','1','','','2019-10-17 10:50:14','','','','','0','0','0','','0','0','0','','ola-sou-o-pedro-brito','','','0'),(901,114,'Pedro Brito','Done!','2019-10-17 13:14:04',138,'0','','','1','','','2019-10-17 13:14:04','uploads/2019/10/17/20191017_100724.jpg','uploads/2019/10/17/20191017_100755.jpg','','','0','0','0','','0','0','0','','done','','','0'),(950,107,'Igor M. Castro','Sherlock Holmes','2019-10-23 17:12:20',131,'0','','','','','','2019-10-23 17:14:25','uploads/2019/10/23/capa_sherlock.jpg','','','','0','0','0','1','0','0','0','1','sherlock-holmes','','','2'),(951,107,'Igor M. Castro','The Little Prince','2019-10-23 17:47:45',131,'0','<p>The Little Prince, French Le Petit Prince, fable and modern classic by French aviator and writer Antoine de Saint-Exup&eacute;ry that was published with his own illustrations in French as Le Petit Prince in 1943. The simple tale tells the story of a child, the little prince, who travels the universe gaining wisdom.</p>','','4','','','2019-10-23 17:47:45','uploads/2019/10/23/prince.jpg','','','','0','0','0','','0','0','0','','the-little-prince','','','2'),(955,120,'Teacher Rachel','For parents! Read Sherlock Holmes for your child.','2019-10-29 16:29:49',141,'0','<p>The Adventures of Sherlock Holmes is a collection of twelve short stories by Arthur Conan Doyle, first published on 14 October 1892.</p>','','1','','','2019-10-29 16:29:49','uploads/2019/10/29/capa_sherlock.jpg','','','','0','0','0','','0','0','0','','for-parents-read-sherlock-holmes-for-your-child','','','0'),(956,120,'Teacher Rachel','Homework! Print and bring painted next Monday.','2019-10-29 16:33:28',141,'0','<p><a class=\"fr-file\" href=\"https://i.froala.com/download/02eb30d0ef308324b4fa96362fae742868c00f20.jpg?1572366792\">paint_butterfly.jpg</a></p><p><a class=\"fr-file\" href=\"https://i.froala.com/download/3ee0ebf4184a8bd42a205482d03208964998a00e.jpg?1572366965\">paint_mouses.jpg</a></p>','','','','','2019-10-29 16:36:18','uploads/2019/10/29/paint_butterfly.jpg','uploads/2019/10/29/paint_mouses.jpg','','','0','0','0','1','0','0','0','1','homework-print-and-bring-painted-next-monday','','','0'),(957,120,'Teacher Rachel','Book reading for weekend!','2019-10-29 16:43:53',141,'0','<p>Hans Christian Andersen was a Danish author. Although a prolific writer of plays, travelogues, novels, and poems, he is best remembered for his fairy tales. &nbsp;Some oh them are:</p><ul><li>The Steadfast Tin Soldier</li><li>The Snow Queen</li><li>You, Little Match Girl</li><li>In the Witch&#39;s Garden</li></ul><p><br></p>','https://www.amazon.co.uk/gp/product/1842704435?tag=prhmarketing2552-21','1','','','2019-10-29 16:43:53','uploads/2019/10/29/tin_soldier.jpg','uploads/2019/10/29/hans.jpg','','','0','0','0','','0','0','0','','book-reading-for-weekend','','','0'),(958,120,'Teacher Rachel','The three little pigs. Listen and tell in the next class.','2019-10-29 16:47:12',141,'0','<p><span class=\"fr-video fr-fvc fr-dvb fr-draggable\" contenteditable=\"false\" draggable=\"true\"><iframe width=\"640\" height=\"360\" src=\"//www.youtube.com/embed/W-WLnxbvMyw?wmode=opaque\" frameborder=\"0\" allowfullscreen=\"\"></iframe></span><br></p>','','1','','','2019-10-29 16:47:12','uploads/2019/10/29/three_pigs.jpg','','','','0','0','0','','0','0','0','','the-three-little-pigs-listen-and-tell-in-the-next-class','','','0'),(960,120,'Teacher Rachel','Homework. Do pages 138 and 139 in book of Maths.','2019-10-29 17:10:49',141,'0','','','1','','','2019-10-29 17:10:49','uploads/2019/10/29/maths_1.jpg','','','','0','0','0','','0','0','0','','homework-do-pages-138-and-139-in-book-of-maths','','','0'),(962,121,'Nike','Tênis Nike Air Zoom Pegasus 36','2019-10-29 18:39:02',142,'0','<p>O ic&ocirc;nico Nike Air Zoom Pegasus 36 retorna com mais perfura&ccedil;&otilde;es e mesh trabalhado no cabedal que visa estrategicamente a respirabilidade em &aacute;reas de alto aquecimento. Um colarinho mais justo no calcanhar e l&iacute;ngua reduz o volume sem comprometer o conforto, enquanto os cabos Flywire expostos proporcionam um ajuste firme em velocidades mais altas.</p><p><br></p><p>Cor: Rosa</p><p><br></p><p>Tamanhos:</p><table style=\"width: 100%;\"><tbody><tr><td style=\"width: 50.0000%;\">Masculino</td><td style=\"width: 50.0000%;\">Feminino</td></tr><tr><td style=\"width: 50.0000%;\">37</td><td style=\"width: 50.0000%;\">36</td></tr><tr><td style=\"width: 50.0000%;\">38</td><td style=\"width: 50.0000%;\">37.5</td></tr><tr><td style=\"width: 50.0000%;\">39</td><td style=\"width: 50.0000%;\">38</td></tr><tr><td>40</td><td>39.5</td></tr><tr><td>41</td><td>41</td></tr><tr><td>42</td><td>41.5</td></tr><tr><td>43</td><td>43</td></tr><tr><td>44</td><td>44</td></tr></tbody></table>','','3','549,99','','2019-10-29 18:39:02','uploads/2019/10/29/pegasus-36_1.jpg','uploads/2019/10/29/pegasus-36-2_1.png','uploads/2019/10/29/pegasus-36-3_1.png','','0','0','0','','0','0','0','','tenis-nike-air-zoom-pegasus-36','','','3'),(963,121,'Nike','Prefontaine was the first athlete to be hired by Nike in 1972.','2019-10-29 19:09:31',142,'0','<p>At the time, the company was just a local distributor in Oregon and was called Blue Ribbon Sports (BRS). He was a major driver of the company&#39;s growth, as well as being a top athlete, he made sure to spread the word about Nike wherever he went, including sending pairs of Nike sneakers to his fellow athletes.</p>','','1','','','2019-10-29 19:09:31','uploads/2019/10/29/prefontaine.jpg','','','','0','0','0','','0','0','0','','prefontaine-was-the-first-athlete-to-be-hired-by-nike-in-1972','','','0'),(964,121,'Nike','Camiseta Nike Barcelona Strike Infantil','2019-10-30 00:44:15',142,'0','<p>A Camiseta Nike Breathe FC Barcelona Strike &eacute; feita com tecido leve e respir&aacute;vel que absorve o suor para ajudar a manter voc&ecirc; fresco e seco. Um painel de mesh nas costas e mangas el&aacute;sticas permitem que voc&ecirc; jogue a todo vapor.</p><p><br></p><p><strong>Benef&iacute;cios</strong></p><ul><li>Tecido Nike Breathe e painel de mesh nas costas ajuda a manter voc&ecirc; seco e fresco.</li><li>A tecnologia Dri-FIT ajuda voc&ecirc; a permanecer seco, confort&aacute;vel e concentrado.</li><li>Mangas el&aacute;sticas permitem que voc&ecirc; se movimente com liberdade.</li><li>Bras&atilde;o e cores do FC Barcelona demonstram o seu orgulho do clube.</li></ul><p><br></p><p><strong>Detalhes do Produto</strong></p><ul><li>Corte acinturado para toque personalizado.</li><li>Tecido: Corpo: 100% poli&eacute;ster reciclado. Pain&eacute;is: 95% poli&eacute;ster/5% spandex.</li><li>Lav&aacute;vel &agrave; m&aacute;quina</li><li>Importado</li></ul><p><br></p><p><strong>Cor:</strong> Cinza</p>','https://www.nike.com.br/Produto/Camiseta-Nike-Barcelona-Strike-Infantil/67-94-98-180806#descricao-completa','3','149,99','','2019-10-30 00:44:15','uploads/2019/10/29/camiseta_barcelona_1.png','uploads/2019/10/29/camiseta_barcelona_2.png','','','0','0','0','','0','0','0','','camiseta-nike-barcelona-strike-infantil','','','3'),(965,121,'Nike','The name Nike comes from the Greek Goddess of victory.','2019-10-30 00:48:23',142,'0','<p>There is a bronze image in Louvre (Paris) whose wing is drawn in a shape similar to the shape of the company symbol.</p>','','1','','','2019-10-30 00:48:23','uploads/2019/10/29/nike-deusa-e1463956541225.jpg','','','','0','0','0','','0','0','0','','the-name-nike-comes-from-the-greek-goddess-of-victory','','','0'),(966,123,'Governo de Portugal','Governo prorroga período crítico de incêndios até 10 de outubro','2019-10-30 00:59:09',144,'0','<p>Durante o per&iacute;odo cr&iacute;tico de inc&ecirc;ndios, nos espa&ccedil;os florestais ou agr&iacute;colas, &eacute; proibido:</p><p>&bull; fumar, fazer lume ou fogueiras;</p><p>&bull; fazer queimas ou queimadas;</p><p>&bull; lan&ccedil;ar foguetes e bal&otilde;es de mecha acesa;</p><p>&bull; fumigar ou desinfestar api&aacute;rios, salvo se os fumigadores estiverem equipados com dispositivos de reten&ccedil;&atilde;o de fa&uacute;lhas;</p><p>&bull; fazer circular, ou utilizar, tratores, m&aacute;quinas e ve&iacute;culos de transporte pesados que n&atilde;o possuam extintor, sistema de reten&ccedil;&atilde;o de fagulhas ou fa&iacute;scas e tapa chamas nos tubos de escape ou chamin&eacute;s.&nbsp;</p>','https://www.portugal.gov.pt/pt/gc21/comunicacao/comunicado?i=governo-prorroga-periodo-critico-de-incendios-ate-10-de-outubro','1','','','2019-10-30 00:59:09','uploads/2019/10/29/incendios.jpg','','','','0','0','0','','0','0','0','','governo-prorroga-periodo-critico-de-incendios-ate-10-de-outubro','','','0'),(967,123,'Governo de Portugal','Risco de incêndios coloca dez distritos sob alerta vermelho','2019-10-30 01:17:15',144,'0','<p>Os 10 distritos s&atilde;o Bragan&ccedil;a, Castelo Branco, Coimbra, Guarda, Lisboa, Portalegre, Santar&eacute;m, Set&uacute;bal, Vila Real e Viseu.</p><p><br></p><p><span class=\"fr-video fr-fvc fr-dvb fr-draggable\" contenteditable=\"false\" draggable=\"true\"><iframe width=\"640\" height=\"360\" src=\"//www.youtube.com/embed/9AN-HfaTARQ?wmode=opaque\" frameborder=\"0\" allowfullscreen=\"\"></iframe></span><br></p><p>O Governo decidiu hoje, por seu lado, declarar a <strong>sit</strong><strong>ua&ccedil;&atilde;o de alerta</strong> em Portugal continental entre as 00:01 de sexta-feira e as 23:59 de s&aacute;bado, devido ao &quot;agravamento do risco de inc&ecirc;ndio&quot; decorrente do estado do tempo.</p>','','1','','','2019-10-30 01:17:15','uploads/2019/10/29/incendios-mapa.jpg','','','','0','0','0','','0','0','0','','risco-de-incendios-coloca-dez-distritos-sob-alerta-vermelho','','','0'),(968,123,'Governo de Portugal','Ajude a combater o incêndio florestal.','2019-10-30 01:26:08',144,'0','<p>Ative o mundo <strong>Portugal against Fire </strong>e marque voc&ecirc; mesmo caso visualize ou esteja pr&oacute;ximo de um inc&ecirc;ndio.</p>','','1','','','2019-10-30 01:26:08','uploads/2019/10/29/incendios-mapa_1.jpg','','','','0','0','0','','0','0','0','','ajude-a-combater-o-incendio-florestal','','','0'),(969,107,'Igor M. Castro','Princípio de incêndio próximo ao campo de futebol','2019-10-30 01:34:08',131,'0','','','1','','','2019-10-30 01:34:08','','','','','0','0','0','','0','0','0','','principio-de-incendio-proximo-ao-campo-de-futebol','-22.84140526173003','-43.31164598464966','1'),(970,124,'Some Restaurant','Receita de Bolinho de bacalhau','2019-10-30 02:29:59',145,'0','<p><strong>Ingredientes</strong></p><ul><li>400g de bacalhau sem pele e espinhas</li><li>3 x&iacute;caras (ch&aacute;) de batata cozida e espremida</li><li>2 colheres (sopa) de cheiro verde picado</li><li>Sal e pimenta do reino a gosto</li><li>3 ovos</li><li>&Oacute;leo para fritar</li></ul><p><br></p><p><strong>Modo de preparo:</strong></p><ol><li>Em uma tigela, coloque o bacalhau de molho em &aacute;gua e deixe descansar na geladeira por 24 horas, trocando a &aacute;gua por 3 vezes.</li><li>Escorra, coloque em uma panela, em fogo m&eacute;dio, cubra com &aacute;gua e cozinhe por 10 minutos.</li><li>Escorra, deixe esfriar e desfie.</li><li>Em uma tigela, misture o bacalhau desfiado, a batata, o cheiro verde, sal e pimenta.</li><li>Adicione os ovos, um a um, misturando com uma colher.</li><li>Modele bolinhos com a ajuda de 2 colheres de sopa e, em uma frigideira, em fogo m&eacute;dio, frite aos poucos, em &oacute;leo quente at&eacute; dourar.Escorra sobre papel absorvente e sirva em seguida.</li></ol>','','','','R. Filipe Folque 46, 1050-114 Lisboa, Portugal','2019-10-30 02:34:31','uploads/2019/10/29/bolinhos.jpg','','','','0','0','0','1','0','0','0','1','receita-de-bolinho-de-bacalhau','','','0'),(971,124,'Some Restaurant','Caldo Verde fácil e rápido','2019-10-30 02:33:45',145,'0','<p><strong>Ingredientes do Caldo verde fácil:</strong></p><ul><li>8 batatas em cubos</li><li>1,5 litros de água</li><li>2 gomos de linguiça calabresa em rodelas</li><li>200g de bacon picado</li><li>1 cebola picada</li><li>5 folhas de couve fatiada</li><li>Sal e pimenta-do-reino a gosto</li><li>Torradas para acompanhar</li></ul><p><br></p><p><strong>Modo de preparo:</strong></p><ul><li>Cozinhe as batatas na água e sal até que estejam macias. Triture com o mixer ou no liquidificador e reserve.</li><li>Em outra panela, em fogo médio e frite a calabresa e o bacon na própria gordura até dourar. Adicione a cebola e refogue por 3 minutos.</li><li>Acrescente a batata batida e cozinhe até ferver. Junte a couve, tempere com sal e pimenta e cozinhe por mais 3 minutos.</li><li>Transfira para uma sopeira e sirva.</li></ul>','','','','R. Filipe Folque 46, 1050-114 Lisboa, Portugal','2019-10-30 02:34:19','uploads/2019/10/29/caldo-verde.jpg','','','','0','0','0','1','0','0','0','1','caldo-verde-facil-e-rapido','','','0');
