CREATE DEFINER=`wasaboomer`@`localhost` PROCEDURE `remove_inactive`()
BEGIN

DELETE a
FROM wsbodb.perfis_avatar a
INNER JOIN wsbodb._usuarios_user u
ON a.user_id=u.id
WHERE u.is_active=0;

DELETE p
FROM wsbodb.perfis_perfil p
INNER JOIN wsbodb._usuarios_user u
ON p.usuario_id = u.id
WHERE u.is_active = 0;
    
DELETE u
FROM wsbodb._usuarios_user u
WHERE u.is_active = 0;

END ;;
